'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const arts=[{src:'assets/first-look-hq.jpg',title:'The first look',label:'PRABHAS & TRIPTII DIMRI',alt:'Spirit original first-look poster featuring Prabhas and Triptii Dimri'},{src:'assets/vivek-hq.jpg',title:'The reveal',label:'VIVEK OBEROI',alt:'Spirit original Vivek Oberoi character-reveal poster'},{src:'assets/release-hq.jpg',title:'World release',label:'05 MARCH 2027',alt:'Spirit release announcement poster'},{src:'assets/title-master.jpg',title:'One bad habit',label:'THE ORIGINAL TITLE CARD',alt:'Spirit official calligraphic title with silver stars'}];
const cast=[{name:'PRABHAS',role:'LEAD ACTOR',text:'Prabhas leads Spirit as an uncompromising police officer, in his first collaboration with Sandeep Reddy Vanga.',src:'assets/first-look-hq.jpg',position:'50% 0%'},{name:'TRIPTII DIMRI',role:'ACTOR',text:'Triptii Dimri stars alongside Prabhas. The first-look campaign brings the two together in an intimate, arresting moment.',src:'assets/first-look-hq.jpg',position:'77% 16%'},{name:'VIVEK OBEROI',role:'ACTOR',text:'Vivek Oberoi joins the world of Spirit. His character-reveal artwork introduces another side of the film’s visual world.',src:'assets/vivek-hq.jpg',position:'50% 0%'},{name:'SANDEEP REDDY VANGA',role:'WRITER & DIRECTOR',text:'The filmmaker behind Spirit. Written and directed by Sandeep Reddy Vanga, and produced by T-Series Films and Bhadrakali Pictures.',src:'assets/director.jpeg',position:'50% 43%',screenshot:true}];
const videos={telugu:{id:'VCGVPiD4BP0',label:'TELUGU'},hindi:{id:'_YhSSfXmr9c',label:'HINDI'}};
const logo=(className='')=>`<span class="logo ${className}"><img src="assets/title-master.jpg" alt="Spirit"></span>`;
const watch=(text='Watch the Sound Story')=>`<button class="watch" data-watch="telugu"><span class="play-ring">▶</span><span>${text}<small>TELUGU · 01:31</small></span></button>`;
const poster=(a,i)=>`<button class="poster-card" data-art="${i}"><img src="${a.src}" alt="${a.alt}" loading="lazy"><span><span><small>${a.label}</small>${a.title}</span><b>↗</b></span></button>`;
const views={
home:()=>`<section class="hero"><div class="hero-images"><img class="scene active" data-scene="0" src="assets/first-look-hq.jpg" alt="Prabhas and Triptii Dimri in Spirit" fetchpriority="high"><img class="scene" data-scene="1" src="assets/vivek-hq.jpg" alt="Vivek Oberoi in Spirit"><video class="scene motion" data-scene="2" src="assets/title-motion.mp4#t=84,90" muted playsinline preload="none" poster="assets/title-master.jpg" aria-label="Spirit title motion"></video></div><div class="hero-shade"></div><div class="light-pass" aria-hidden="true"></div><div class="star-credit"><span>INDIA’S BIGGEST SUPERSTAR</span><strong>PRABHAS</strong></div><div class="hero-identity"><p>GULSHAN KUMAR & T-SERIES PRESENT</p><h1 class="logo"><img src="assets/title-master.jpg" alt="Spirit"></h1><div class="director-credit"><span>THE FILM BY</span><b>SANDEEP REDDY VANGA</b></div><div class="hero-actions">${watch()}<a href="#/film" class="text-link">Explore the film <span>↗</span></a></div></div><div class="hero-date"><span>WORLDWIDE IN CINEMAS</span><strong>05 <i>/</i> 03 <i>/</i> 2027</strong></div><div class="hero-bottom"><div class="scene-buttons" role="group" aria-label="Choose a scene">${['First look','Another world','Title motion'].map((n,i)=>`<button data-scene-select="${i}" aria-pressed="${i===0}"><small>0${i+1}</small>${n}<i></i></button>`).join('')}</div><button class="scroll-cue" id="scroll-story">SCROLL TO DISCOVER <span>↓</span></button></div></section>
<section class="story-section" id="story"><div class="story-photo"><img src="assets/first-look-hq.jpg" alt="Prabhas and Triptii Dimri in the first look" loading="lazy"></div><div class="story-copy reveal"><span class="kicker">THE FIRST COLLABORATION</span><h2>PRABHAS.<br>SANDEEP REDDY VANGA.</h2><p>An uncompromising cop. A new world from Sandeep Reddy Vanga. Spirit brings Prabhas into the filmmaker’s next action drama.</p><a class="text-link" href="#/film">Inside the film <span>↗</span></a></div></section>
<section class="reel-section"><video class="reel-video" src="assets/title-motion.mp4#t=84,90" muted playsinline preload="none" poster="assets/title-master.jpg" aria-label="Spirit campaign title sequence"></video><div class="reel-copy reveal"><span class="kicker">IT BEGINS WITH A VOICE.</span><h2>THE SOUND<br>STORY.</h2>${watch('Enter the theatre')}</div><a href="#/theatre" class="reel-all">All films & motion ↗</a></section>
<section class="pad"><div class="section-top"><span class="kicker">FROM THE WORLD OF SPIRIT</span><a href="#/gallery" class="text-link">View the gallery ↗</a></div><div class="poster-grid">${arts.slice(0,2).map(poster).join('')}</div></section>
<section class="release pad"><span class="kicker">WORLD RELEASE</span><h2>5 MARCH <em>2027.</em></h2><div class="countdown">${['days','hours','minutes','seconds'].map(n=>`<span><b data-time="${n}">—</b>${n.toUpperCase()}</span>`).join('')}</div><p>Telugu · Hindi · Tamil · Malayalam · Kannada<br>Mandarin · Japanese · Korean</p><small>Announced theatrical release. Plans may change.</small></section>`,
film:()=>`<section class="film-hero"><img src="assets/first-look-hq.jpg" alt="Spirit first-look campaign artwork"><div><span class="kicker">A SANDEEP REDDY VANGA FILM</span><h1 class="logo"><img src="assets/title-master.jpg" alt="Spirit"></h1><p>THE FIRST COLLABORATION. A NEW CHAPTER.</p></div></section><section class="film-about pad"><span class="kicker">THE FILM</span><div><h2>AN UNCOMPROMISING COP.<br><em>A WORLD YET TO UNFOLD.</em></h2><p>Prabhas leads Spirit, written and directed by Sandeep Reddy Vanga. T-Series describes the project as an action drama centered on a fierce, uncompromising police officer.</p><p>The released Sound Story introduces a prison setting and the arrival of a former officer. The rest of his story is still to come.</p><a class="text-link" href="#/cast">Meet the cast & crew ↗</a></div></section><section class="timeline pad"><span class="kicker">THE JOURNEY SO FAR</span>${[['23 OCT 2025','A voice. One bad habit.','The Sound Story is released.','theatre'],['01 JAN 2026','The first look.','Prabhas and Triptii Dimri.','gallery'],['16 JAN 2026','A date with the world.','March 5, 2027 is announced.','gallery'],['27 FEB 2026','Another side of Spirit.','Vivek Oberoi’s reveal.','gallery']].map(x=>`<a href="#/${x[3]}"><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p><b>↗</b></a>`).join('')}</section><section class="reel-section"><video class="reel-video" src="assets/title-motion.mp4#t=84,90" muted playsinline preload="none" poster="assets/title-master.jpg"></video><div class="reel-copy"><span class="kicker">CONTINUE INTO THE WORLD</span><h2>THE SOUND STORY.</h2>${watch()}</div></section>`,
cast:()=>`<section class="cast-hero"><div class="cast-photo" id="cast-photo"></div><div class="cast-wash"></div><div class="cast-heading"><span class="kicker">CAST & CREW</span></div><div class="cast-info" id="cast-info"></div><div class="cast-tabs" role="group" aria-label="Select cast member">${cast.map((p,i)=>`<button data-person="${i}" aria-pressed="${i===0}"><small>0${i+1}</small>${p.name}</button>`).join('')}</div></section><section class="crew pad"><span class="kicker">A T-SERIES FILMS & BHADRAKALI PICTURES PRODUCTION</span><h2>THE FILMMAKERS.</h2><div class="crew-grid">${[['WRITTEN & DIRECTED BY','Sandeep Reddy Vanga'],['PRODUCED BY','Bhushan Kumar<br>Pranay Reddy Vanga<br>Krishan Kumar<br>Prabhakar Reddy Vanga'],['DIRECTOR OF PHOTOGRAPHY','Raj Thota'],['BACKGROUND SCORE','Harshavardhan Rameshwar'],['PRODUCTION DESIGN','Suresh Selvarajan'],['SOUND DESIGN','Sync Cinema']].map(x=>`<div><span>${x[0]}</span><h3>${x[1]}</h3></div>`).join('')}</div><p>Credits as shown on the released promotional artwork.</p></section>`,
theatre:()=>`<section class="inner-page theatre-page pad"><div class="theatre-heading"><span class="kicker">THE SCREENING ROOM</span><h1>SPIRIT. <em>IN MOTION.</em></h1><p>Watch the released Sound Story from T-Series.</p></div><div class="screen"><video id="theatre-player" src="assets/title-motion.mp4" poster="assets/title-master.jpg" controls playsinline preload="metadata" aria-label="Spirit Telugu Sound Story"></video><div class="screen-meta"><span>#ONEBADHABIT <i>THE SOUND STORY</i></span><span>TELUGU · 01:31</span></div></div><div class="screen-list"><h2>WATCH FROM T-SERIES</h2>${['telugu','hindi'].map((x,i)=>`<button data-watch="${x}"><span>0${i+1}</span><strong>${x==='telugu'?'Telugu':'Hindi'}</strong><small>Original Sound Story</small><b>▶</b></button>`).join('')}</div><p class="theatre-note">Embedded video is served by YouTube. If playback is unavailable, use the direct official-channel link. The local Telugu copy is the published campaign clip; higher quality may be available on the official channel.</p></section>`,
gallery:()=>`<section class="inner-page pad"><div class="page-heading"><div><span class="kicker">THE CAMPAIGN ARCHIVE</span><h1>THE WORLD,<br><em>FRAME BY FRAME.</em></h1></div><p>Original released artwork.<br>Explore in full screen.</p></div><div class="poster-grid">${arts.map(poster).join('')}</div><div class="gallery-end"><span>ORIGINAL FILM ARTWORK</span><a href="#/credits">Sources & credits ↗</a></div></section>`,
sound:()=>`<section class="sound-page inner-page pad">${logo('sound-watermark')}<div class="sound-main"><span class="kicker">THE SOUND OF SPIRIT</span><h1>#ONEBADHABIT</h1><p>THE SOUND STORY · TELUGU</p><div class="wave" id="wave" aria-hidden="true">${'<i></i>'.repeat(64)}</div><div class="transport"><button id="rewind" aria-label="Rewind 10 seconds">↶<small>10</small></button><button id="play-audio" class="big-play" aria-label="Play Sound Story">▶</button><button id="forward" aria-label="Forward 10 seconds">↷<small>10</small></button></div><div class="seek-row"><span id="elapsed">0:00</span><input id="seek" type="range" min="0" max="100" step="0.1" value="0" aria-label="Audio playback position"><span id="duration">1:31</span></div><div class="volume-row"><label>Volume <input id="volume" type="range" min="0" max="100" value="45"><output id="volume-value">45%</output></label><button id="restart-audio" class="text-link">Restart ↺</button></div><p class="track-info" id="track-info">Supplied Telugu Sound Story · best with headphones</p><div class="audio-file-row"><label class="file-label">Choose your own audio<input id="file-audio" type="file" accept="audio/*"></label><button id="restore-audio">Restore Spirit soundtrack</button></div><div class="preferences"><label><input id="reduce" type="checkbox"> Reduced motion</label><button id="fullscreen">Fullscreen ↗</button></div></div></section>`,
credits:()=>`<section class="credits-page inner-page pad"><span class="kicker">THE PROJECT</span><h1>CREDITS<br>& SOURCES.</h1><p>This independent website concept celebrates Spirit. It is not the film’s official website and is not affiliated with T-Series, Bhadrakali Pictures, or the filmmakers. All campaign artwork, audio, video and film marks belong to their respective owners.</p><div class="sources">${[['Film premise & production — T-Series','https://www.tseries.com/news/prabhas%E2%80%93sandeep-reddy-vanga%E2%80%99s-spirit-begins-filming-muhurat-held-hyderabad-chiranjeevi-chief'],['Telugu Sound Story — T-Series Telugu','https://www.youtube.com/watch?v=VCGVPiD4BP0'],['Hindi Sound Story — T-Series','https://www.youtube.com/watch?v=_YhSSfXmr9c'],['First-look campaign artwork — Hindustan Times','https://www.hindustantimes.com/entertainment/telugu-cinema/spirit-first-look-prabhas-shows-up-in-bruised-avatar-as-triptii-dimri-lights-his-cigarette-101767230199593.html'],['Campaign updates — inSpiritMode','https://www.instagram.com/inspiritmode/'],['Announced release date — NDTV','https://www.ndtv.com/entertainment/salman-khan-vs-prabhas-in-eid-2027-spirit-makers-confirm-march-5-release-11929509'],['Published Telugu motion clip — Telugu Bulletin','https://www.telugubulletin.com/prabhas-spirit-sound-story-ignites-fans-hearts-in-five-indian-languages-224840']].map(x=>`<a href="${x[1]}" target="_blank" rel="noopener">${x[0]} ↗</a>`).join('')}</div><p>The film identity uses authentic title artwork from the released campaign, rather than a substitute font. Lead posters are 2143 × 3000 pixels. The local motion clip is 848 × 480; use the official YouTube versions for available streaming quality. The site does not claim native 4K film footage.</p><button id="replay" class="primary">Replay opening <span>↗</span></button></section>`
};
let route='home',transitioning=false,sceneIndex=0,activeArt=0,timer,observer,customURL,customName='',context,analyser,bins,mediaSource,energy=0,castVersion=0,resumeAfterVideo=false;
let reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;try{reduced=reduced||localStorage.getItem('spirit-motion')==='reduce'}catch{}document.body.classList.toggle('reduced',reduced);
const audio=$('#soundtrack');audio.volume=.45;
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function currentRoute(){const p=decodeURIComponent(location.hash).replace(/^#\/?/,'').split('#')[0];return Object.hasOwn(views,p)?p:'home'}
function render(){clearInterval(timer);observer?.disconnect();$$('main video').forEach(v=>v.pause());route=currentRoute();$('#main').innerHTML=views[route]();document.body.dataset.page=route;document.title='Spirit — '+({home:'A Sandeep Reddy Vanga Film',film:'The Film',cast:'Cast & Crew',theatre:'Theatre',gallery:'Gallery',sound:'The Sound Story',credits:'Credits & Sources'}[route]);$$('header nav a').forEach(a=>{const on=a.hash==='#/'+route;a.classList.toggle('active',on);on?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});window.scrollTo({top:0,behavior:'instant'});bindPage()}
async function navigate(){if(transitioning)return;transitioning=true;if(!reduced){$('#shutter').classList.add('cover');await new Promise(r=>setTimeout(r,530))}render();$('#shutter').classList.remove('cover');transitioning=false}addEventListener('hashchange',navigate);
function closeDialog(d){d.close();if(d.id==='menu')$('#menu-open').setAttribute('aria-expanded','false');if(d.id==='video-dialog'){$('#video-stage').replaceChildren();if(resumeAfterVideo){resumeAfterVideo=false;playAudio()}}}
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>closeDialog(b.closest('dialog'))));$$('dialog').forEach(d=>{d.addEventListener('cancel',()=>{if(d.id==='video-dialog'){$('#video-stage').replaceChildren();if(resumeAfterVideo){resumeAfterVideo=false;playAudio()}}});d.addEventListener('close',()=>{if(d.id==='menu')$('#menu-open').setAttribute('aria-expanded','false')})});$('#menu-open').addEventListener('click',()=>{$('#menu').showModal();$('#menu-open').setAttribute('aria-expanded','true')});$('#menu').addEventListener('click',e=>{if(e.target.closest('a'))closeDialog($('#menu'))});$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({behavior:'instant'})});
function openVideo(language){const v=videos[language]||videos.telugu;resumeAfterVideo=!audio.paused;audio.pause();$$('main video').forEach(el=>el.pause());$('#video-title').textContent=`SPIRIT / THE SOUND STORY / ${v.label}`;$('#youtube-link').href=`https://www.youtube.com/watch?v=${v.id}`;const iframe=document.createElement('iframe');iframe.src=`https://www.youtube-nocookie.com/embed/${v.id}?autoplay=1&rel=0`;iframe.title=`Spirit official ${v.label} Sound Story`;iframe.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';$('#video-stage').replaceChildren(iframe);$('#video-dialog').showModal()}
function openArt(n){activeArt=(n+arts.length)%arts.length;const a=arts[activeArt],img=new Image();img.src=a.src;img.alt=a.alt;$('#art-stage').replaceChildren(img);$('#art-caption').textContent=a.label+' / '+a.title;$('#art-count').textContent=String(activeArt+1).padStart(2,'0')+' / 04';$('#download-art').href=a.src;$('#download-art').download='spirit-'+a.title.replaceAll(' ','-').toLowerCase()+'.jpg';if(!$('#art-dialog').open)$('#art-dialog').showModal()}
$('#art-prev').addEventListener('click',()=>openArt(activeArt-1));$('#art-next').addEventListener('click',()=>openArt(activeArt+1));$('#art-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();openArt(activeArt-1)}if(e.key==='ArrowRight'){e.preventDefault();openArt(activeArt+1)}});
function loopVideo(v){if(v)v.addEventListener('timeupdate',()=>{if(v.currentTime>=90)v.currentTime=84})}
function bindPage(){
 $$('[data-art]',$('#main')).forEach(b=>b.addEventListener('click',()=>openArt(Number(b.dataset.art))));$$('[data-watch]',$('#main')).forEach(b=>b.addEventListener('click',()=>openVideo(b.dataset.watch)));
 observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.target.tagName==='VIDEO'){if(e.isIntersecting&&!reduced&&!document.body.classList.contains('entering')){if(e.target.currentTime<84||e.target.currentTime>90)e.target.currentTime=84;e.target.play().catch(()=>{})}else e.target.pause()}else if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.2});$$('.reveal').forEach(el=>observer.observe(el));$$('.reel-video').forEach(v=>{loopVideo(v);observer.observe(v)});
 if(route==='home'){sceneIndex=0;$$('[data-scene-select]').forEach(b=>b.addEventListener('click',()=>selectScene(Number(b.dataset.sceneSelect),true)));$('#scroll-story').addEventListener('click',()=>$('#story').scrollIntoView({behavior:reduced?'instant':'smooth'}));loopVideo($('.scene.motion'));if(!reduced)timer=setInterval(()=>{if(!document.hidden&&!document.body.classList.contains('entering')&&!document.querySelector('dialog[open]'))selectScene((sceneIndex+1)%2)},16000)}
 if(route==='cast'){selectPerson(0,false);$$('[data-person]').forEach(b=>b.addEventListener('click',()=>selectPerson(Number(b.dataset.person),true)))}
 if(route==='sound')bindSound();if(route==='theatre'){$('#theatre-player').addEventListener('play',()=>audio.pause());$('#theatre-player').addEventListener('error',()=>notify('Use the official T-Series screening below if local playback is unavailable.'))}$('#replay')?.addEventListener('click',showEntry);syncAudio();countdown();
}
function selectScene(n,manual=false){sceneIndex=n;$$('[data-scene]').forEach((el,i)=>{el.classList.toggle('active',i===n);if(el.tagName==='VIDEO'){if(i===n){el.currentTime=84;el.play().catch(()=>notify('Visit the theatre to play the motion clip.'))}else el.pause()}});$$('[data-scene-select]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)));if(manual)clearInterval(timer)}
async function selectPerson(n,animate){const version=++castVersion,p=cast[n],photo=$('#cast-photo');if(animate&&!reduced){photo.classList.add('changing');await new Promise(r=>setTimeout(r,300));if(version!==castVersion||!photo.isConnected)return}photo.style.backgroundImage=`url('${p.src}')`;photo.style.backgroundPosition=p.position;photo.style.backgroundSize=p.screenshot?'auto 200%':n===1?'auto 180%':'auto 210%';photo.classList.remove('changing');$('#cast-info').innerHTML=`<span class="kicker">${p.role}</span><h1>${p.name}</h1><p>${p.text}</p>`;$$('[data-person]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)))}
function initAudio(){if(context)return;context=new(window.AudioContext||window.webkitAudioContext)();analyser=context.createAnalyser();analyser.fftSize=128;bins=new Uint8Array(analyser.frequencyBinCount);mediaSource=context.createMediaElementSource(audio);mediaSource.connect(analyser);analyser.connect(context.destination)}
async function playAudio(){try{initAudio();await context.resume();await audio.play()}catch{notify('Audio could not start. Tap play again or choose a supported audio file.')}}function toggleAudio(){audio.paused?playAudio():audio.pause()}
$('#audio-toggle').addEventListener('click',toggleAudio);audio.addEventListener('play',syncAudio);audio.addEventListener('pause',syncAudio);audio.addEventListener('timeupdate',playback);audio.addEventListener('loadedmetadata',playback);audio.addEventListener('error',()=>notify('This audio file could not play. Restore Spirit or choose MP3/WAV.'));
function syncAudio(){const on=!audio.paused;document.body.classList.toggle('sound-on',on);$('#audio-toggle').setAttribute('aria-pressed',String(on));$('#audio-toggle').setAttribute('aria-label',on?'Pause Spirit soundtrack':'Play Spirit soundtrack');$('#audio-label').textContent=on?'Sound on':'Sound off';if($('#play-audio')){$('#play-audio').textContent=on?'Ⅱ':'▶';$('#play-audio').setAttribute('aria-label',on?'Pause Sound Story':'Play Sound Story')}playback()}
const time=n=>Number.isFinite(n)?`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`:'0:00';function playback(){if(!$('#seek'))return;$('#elapsed').textContent=time(audio.currentTime);$('#duration').textContent=time(audio.duration);$('#seek').value=Number.isFinite(audio.duration)?audio.currentTime/audio.duration*100:0}
function bindSound(){
 $('#play-audio').addEventListener('click',toggleAudio);$('#rewind').addEventListener('click',()=>audio.currentTime=Math.max(0,audio.currentTime-10));$('#forward').addEventListener('click',()=>{if(Number.isFinite(audio.duration))audio.currentTime=Math.min(audio.duration,audio.currentTime+10)});$('#restart-audio').addEventListener('click',()=>audio.currentTime=0);$('#seek').addEventListener('input',e=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)/100*audio.duration});$('#volume').value=audio.volume*100;$('#volume-value').value=Math.round(audio.volume*100)+'%';$('#volume').addEventListener('input',e=>{audio.volume=Number(e.target.value)/100;$('#volume-value').value=e.target.value+'%'});if(customName)$('#track-info').textContent='Your local audio · '+customName;
 $('#file-audio').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('audio/')&&!/\.(mp3|wav|m4a|ogg|aac|flac)$/i.test(file.name)){notify('Choose an audio file such as MP3 or WAV.');return}audio.pause();if(customURL)URL.revokeObjectURL(customURL);customURL=URL.createObjectURL(file);audio.src=customURL;customName=file.name;$('#track-info').textContent='Your local audio · '+file.name;notify('Audio ready. Press play. Your file stays on this device.')});$('#restore-audio').addEventListener('click',()=>{audio.pause();audio.src='assets/one-bad-habit-telugu.mp3';if(customURL)URL.revokeObjectURL(customURL);customURL=null;customName='';$('#track-info').textContent='Supplied Telugu Sound Story · best with headphones';notify('Spirit soundtrack restored.')});
 $('#reduce').checked=reduced;$('#reduce').addEventListener('change',e=>{reduced=e.target.checked;document.body.classList.toggle('reduced',reduced);window.SpiritCinema?.setReducedMotion(reduced);try{localStorage.setItem('spirit-motion',reduced?'reduce':'full')}catch{}});$('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else notify('Fullscreen is unavailable in this browser.')}catch{notify('Fullscreen is unavailable in this browser.')}});
}
function countdown(){const left=Math.max(0,Date.parse('2027-03-05T00:00:00+05:30')-Date.now()),v={days:Math.floor(left/86400000),hours:Math.floor(left/3600000)%24,minutes:Math.floor(left/60000)%60,seconds:Math.floor(left/1000)%60};$$('[data-time]').forEach(el=>el.textContent=String(v[el.dataset.time]).padStart(2,'0'))}setInterval(countdown,1000);
function leaveEntry(withSound){if(withSound)playAudio();$('#entry-video').pause();$('#entry').classList.add('out');document.body.classList.remove('entering');[$('#main'),$('header'),$('footer')].forEach(el=>el.removeAttribute('inert'));$('#main').focus({preventScroll:true});try{sessionStorage.setItem('spirit-entered','1')}catch{}setTimeout(()=>$('#entry').hidden=true,1100)}
function showEntry(){preload();audio.pause();$('#entry').hidden=false;$('#entry').classList.remove('out');document.body.classList.add('entering');[$('#main'),$('header'),$('footer')].forEach(el=>el.setAttribute('inert',''));if(!reduced){$('#entry-video').currentTime=84;$('#entry-video').play().catch(()=>{})}$('#enter-sound').focus()}
$('#enter-sound').addEventListener('click',()=>leaveEntry(true));$('#enter-silent').addEventListener('click',()=>leaveEntry(false));$('#skip-entry').addEventListener('click',()=>leaveEntry(false));$('#entry').addEventListener('keydown',e=>{if(e.key==='Escape')leaveEntry(false);if(e.key==='Tab'){const buttons=[$('#skip-entry'),$('#enter-sound'),$('#enter-silent')],i=buttons.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();buttons[2].focus()}else if(!e.shiftKey&&i===2){e.preventDefault();buttons[0].focus()}}});
async function preload(){let count=0;await Promise.all(['assets/title-master.jpg','assets/first-look-hq.jpg','assets/vivek-hq.jpg'].map(src=>new Promise(resolve=>{const img=new Image();const done=()=>{count++;const n=Math.round(count/3*100);$('#load-number').textContent=n+'%';$('#load-bar').style.width=n+'%';resolve()};img.onload=done;img.onerror=done;img.src=src})));$('#load-label').textContent='THE EXPERIENCE IS READY'}
render();window.SpiritCinema?.init({canvas:$('#atmosphere'),reducedMotion:reduced,getEnergy:()=>energy});loopVideo($('#entry-video'));let entered=false;try{entered=sessionStorage.getItem('spirit-entered')==='1'}catch{}if(entered){$('#entry').hidden=true;document.body.classList.remove('entering')}else{showEntry();preload()}
let lastFrame=0;function tick(t){requestAnimationFrame(tick);if(document.hidden||t-lastFrame<33)return;lastFrame=t;if(analyser&&!audio.paused){analyser.getByteFrequencyData(bins);energy=bins.slice(0,10).reduce((a,b)=>a+b,0)/2550}else energy*=.92;$$('#wave i').forEach((el,i)=>el.style.height=(reduced||audio.paused?2:3+(bins?.[i]||0)*.42)+'px');if(!reduced&&route==='home'&&!document.body.classList.contains('entering')){const cam=window.SpiritCinema?.camera,active=$('.scene.active');if(cam&&active?.tagName==='IMG')active.style.transform=`scale(1.035) translate3d(${cam.x*8}px,${-cam.y*6+Math.min(scrollY,1000)*.055}px,0)`;const img=$('.story-photo img');if(img){const r=img.closest('.story-section').getBoundingClientRect();if(r.top<innerHeight&&r.bottom>0)img.style.transform=`scale(${1.03+Math.max(0,-r.top)*.00006})`}}}requestAnimationFrame(tick);document.addEventListener('visibilitychange',()=>{if(document.hidden){$$('video').forEach(v=>v.pause());audio.pause()}});



